       "../bin/cuda12/onnxruntime_providers_cuda.dll": "onnxruntime_providers_cuda.dll",
       "../bin/cuda12/onnxruntime_providers_shared.dll": "onnxruntime_providers_shared.dll",
       "../bin/cuda12/cudnn64_9.dll": "cudnn64_9.dll",
       "../bin/cuda12/cudnn_ops64_9.dll": "cudnn_ops64_9.dll",
       "../bin/cuda12/cudnn_cnn64_9.dll": "cudnn_cnn64_9.dll",
       "../bin/cuda12/cudnn_graph64_9.dll": "cudnn_graph64_9.dll",
       "../bin/cuda12/cudnn_adv64_9.dll": "cudnn_adv64_9.dll"
     }
     ```
3. **第 3 步：执行发布构建**
   - 运行 `uv run --python 3.11 C:\dev\ai-forge\publish_update.py` 生成全新的安装包与热更新包（包体约 850 MB，远低于 NSIS 2GB 限制）。
4. **第 4 步：安装包真实环境验收**
   - 安装客户端并运行超分，断言 1~6 块连续全速推进并在几秒内弹出“处理成功”。

---

## 6. 避坑指南（新会话绝对不要再踩的 5 大雷区）

1. ❌ **严禁随意删除 `cublasLt64_13.dll`**：它是 CUDA 13 矩阵计算的刚性依赖，绝不能因其体积 428MB 就将其排除。
2. ❌ **严禁将未使用的 CUDA 12 库（`cublasLt64_12.dll` 637MB）与全架构预编译包（521MB）塞回安装包**：否则总待打包体积将超过 2.0 GB，再次触发 NSIS `error mmapping file out of range` 崩溃。
3. ❌ **严禁在 Vue 3 中用 `ref()` 包装 Tauri 原生 Class 实例**：Vue 3 的深层 Proxy 会破坏原生类的私有字段（`#rid`），热更新等功能必须交由 Rust 原生 Command 处理。
4. ❌ **严禁依赖开发态的“看起来跑通”**：开发机全局 `PATH` 会兜底载入系统 DLL。必须以 PE 静态导入表报告（`parse_pe_imports.py`）和独立安装环境为唯一真值验收标准。
5. ❌ **严禁在命令行开头带有 `#` 注释**：PowerShell 执行带有 `#` 注释的单行命令会导致整行被跳过或解析异常。// 🛡️ 紫电 AI 桌面工坊 - 全能格式转换专属强类型契约 (format-converter.ts)
import { invoke } from "@tauri-apps/api/core";
export interface FormatConvertTask {
  /** 待转换源文件物理绝对路径 */
  input_path: string;
  /** 目标扩展名 (如 mp3, flac, json, md, docx, epub, ico, pdf, extract 等) */
  target_format: string;
  /** 可选输出目录，未指定时默认输出到源文件同级目录 */
  output_dir?: string | null;
}
export interface FormatConvertResult {
  /** 是否转换成功 */
  success: boolean;
  /** 源文件路径 */
  input_path: string;
  /** 转换产物输出物理路径 */
  output_path?: string | null;
  /** 实际嗅探/转换的格式 */
  detected_format: string;
  /** 异常或成功描述信息 */
  message?: string | null;
}
export async function runFormatConvert(task: FormatConvertTask): Promise<FormatConvertResult> {
  return await invoke<FormatConvertResult>("run_format_convert", { task });
}// 🛡️ 紫电 AI 桌面工坊 - 4K/8K 视觉超分专属强类型契约 (upscale-48k.ts)
import { invoke } from "@tauri-apps/api/core";
export interface UpscaleTask {
  /** 待超分输入图像物理绝对路径 */
  input_path: string;
  /** 超分结果输出物理绝对路径 */
  output_path: string;
  /** 可选指定的 ONNX 模型物理路径 */
  model_path?: string | null;
  /** 目标放大倍率 (如 2.0, 4.0, 8.0) */
  target_scale?: number | null;
  /** 智能封顶最大物理边长 (4K 极速: 3840, 8K 旗舰: 8192) */
  max_output_side?: number | null;
  /** 切块网格尺寸 (默认 256 或 512) */
  tile_size?: number | null;
  /** 切块重叠 Padding 消除接缝 (默认 10) */
  tile_pad?: number | null;
}
export interface UpscaleResult {
