            <span
              v-if="latestVersion"
              class="px-2 py-0.5 rounded-full bg-[#02c3b4]/15 border border-[#02c3b4]/40 text-[#02c3b4] font-mono text-[10px] font-bold"
            >
              v{{ latestVersion }}
            </span>
          </div>
          <p class="text-xs text-[#8b999b] font-medium mt-0.5">
            紫电 AI 官方更新就绪，享受最新算子与极致体验
          </p>
        </div>
      </div>
      <!-- 更新日志说明框 -->
      <div
        class="p-4 rounded-2xl bg-white/[0.03] border border-white/10 space-y-2 text-xs text-slate-300 max-h-[160px] overflow-y-auto custom-scrollbar"
      >
        <div class="flex items-center gap-1.5 text-[#02c3b4] font-bold">
          <Sparkles :size="13" />
          <span>更新内容速览：</span>
        </div>
        <div class="whitespace-pre-wrap leading-relaxed text-[#c4d4d6]">
          {{ updateBody || '• 全系统协同性能与显存守卫深度优化\n• 修复已知问题，提升端侧推演流畅度' }}
        </div>
      </div>
      <!-- 下载进度条 -->
      <div v-if="isUpdating" class="w-full space-y-1.5 pt-1">
        <div class="w-full h-2 bg-white/10 rounded-full overflow-hidden">
          <div
            class="h-full bg-gradient-to-r from-[#02c3b4] to-[#bc05ff] rounded-full transition-all duration-200"
            :style="{ width: `${progressPercent}%` }"
          ></div>
        </div>
        <div class="flex justify-between text-[11px] font-mono text-[#8b999b]">
          <span>正在由 Rust 核心极速拉取并校验签名...</span>
          <span>{{ formatBytes(downloadedBytes) }} / {{ formatBytes(totalBytes) }} ({{ progressPercent }}%)</span>
        </div>
      </div>
      <!-- 错误提示 -->
      <div v-if="errorMessage" class="text-xs text-rose-400 bg-rose-500/10 p-2.5 rounded-xl border border-rose-500/20">
        {{ errorMessage }}
      </div>
      <!-- 底部按钮组 -->
      <div class="w-full flex items-center justify-between gap-3 pt-1">
        <button
          v-if="!isUpdating"
          type="button"
          @click="handleDismiss"
          class="flex-1 py-3 px-4 rounded-2xl bg-white/[0.04] hover:bg-white/[0.08] text-[#8b999b] hover:text-white font-bold text-xs transition-all active:scale-95 cursor-pointer border border-white/10"
        >
          稍后提醒
        </button>
        <button
          type="button"
          :disabled="isUpdating"
          @click="handleStartUpdate"
          class="flex-1 py-3 px-4 rounded-2xl bg-gradient-to-r from-[#02c3b4] to-[#00d2ff] hover:opacity-95 text-slate-950 font-black text-xs transition-all active:scale-95 cursor-pointer flex items-center justify-center gap-1.5 shadow-[0_0_20px_rgba(2,195,180,0.3)]"
        >
          <RefreshCw v-if="isUpdating" :size="14" class="animate-spin" />
          <span>{{ isUpdating ? `正在安装更新 (${progressPercent}%)...` : '立即升级并重启' }}</span>
        </button>
      </div>
    </div>
  </div>
</template><script setup lang="ts">
import { ref, computed, onMounted, onUnmounted } from 'vue';
import { useUIStore } from '../../store/uiStore';
import { listen, type UnlistenFn } from '@tauri-apps/api/event';
import {
  downloadToolDependencies,
  cancelDependencyDownloads,
  type DependencyItem,
  type DependencyProgressPayload,
} from '../../bindings';
import { Download, Loader2 } from 'lucide-vue-next';
const ui = useUIStore();
const isDownloading = ref(false);
const progressMap = ref<Record<string, DependencyProgressPayload>>({});
let unlistenProgress: UnlistenFn | null = null;
// 1. 统一极简标题
const modalTitle = computed(() => '需要模型依赖');
// 2. 统一各工具极简说明文案（100% 统一工具命名）
const modalDesc = computed(() => {
  switch (ui.dependencyTargetTool) {
    case 'asr':
    case 'video-subtitle':
      return '首次使用「视频字幕生成」需下载本地离线模型，完成后自动进入。';
    case 'upscale':
    case 'upscale-48k':
      return '首次使用「4K/8K 图像超分」需下载本地离线模型，完成后自动进入。';
    case 'pdf':
    case 'pdf-parse':
      return '首次使用「PDF 智能解析」需下载本地离线模型，完成后自动进入。';
    default:
      return '当前功能需要下载本地离线模型，下载完成后自动进入。';
  }
});
// 计算总体下载进度 (0 - 100%)
const overallPercent = computed(() => {
  const items = ui.dependencyItems;
  if (!items || items.length === 0) return 100;
  let totalPercent = 0;
  for (const item of items) {
    if (item.is_ready) {
      totalPercent += 100;
      continue;
    }
    const prog = progressMap.value[item.id];
    if (prog) {
      if (prog.phase === 'complete') totalPercent += 100;
      else if (prog.phase === 'verifying') totalPercent += 98;
      else totalPercent += prog.percent || 0;
    }
  }
  return Math.min(100, Math.round(totalPercent / items.length));
});
const getItemStatusText = (item: DependencyItem) => {
  if (item.is_ready) return '已就绪';
  const prog = progressMap.value[item.id];
  if (!prog) return '等待下载';
  if (prog.phase === 'verifying') return '正在校验...';
  if (prog.phase === 'complete') return '已就绪';
  return `下载中 ${prog.percent}%`;
};
const getItemStatusClass = (item: DependencyItem) => {
  if (item.is_ready) return 'text-emerald-600 font-bold';
  const prog = progressMap.value[item.id];
  if (!prog) return 'text-slate-400 font-bold';
  if (prog.phase === 'verifying') return 'text-amber-500 font-bold';
  if (prog.phase === 'complete') return 'text-emerald-600 font-bold';
  return 'text-[#02c3b4] font-bold';
};
const handleStartDownload = async () => {
  if (isDownloading.value || !ui.dependencyTargetTool) return;
  isDownloading.value = true;
  try {
    const success = await downloadToolDependencies(ui.dependencyTargetTool);
    if (success) {
      ui.弹出提示('🎉 依赖模型已全部就绪！', 'success');
      isDownloading.value = false;
      const targetTool = ui.dependencyTargetTool;
      const cb = ui.dependencyCallback;
      ui.closeDependencyModal();
      if (cb) {
        cb();
      } else if (targetTool) {
        ui.currentView = targetTool as any;
      }
    }
  } catch (err: any) {
    isDownloading.value = false;
    ui.弹出提示(`🚨 依赖下载异常: ${err}`, 'error');
  }
};
const handleCancel = async () => {
  if (isDownloading.value) {
    try {
      await cancelDependencyDownloads();
      ui.弹出提示('已取消依赖下载', 'info');
    } catch {}
  }
  isDownloading.value = false;
  ui.closeDependencyModal();
};
onMounted(async () => {
  try {
    unlistenProgress = await listen<DependencyProgressPayload>(
      'dependency-download-progress',
      (event) => {
        const payload = event.payload;
        if (!payload?.item_id) return;
        progressMap.value[payload.item_id] = payload;
        if (payload.phase === 'complete') {
          const matched = ui.dependencyItems.find((i) => i.id === payload.item_id);
          if (matched) matched.is_ready = true;
        }
      }
    );
  } catch (e) {
    console.warn('⚠️ 依赖下载进度事件监听未激活:', e);
  }
});
onUnmounted(() => {
  if (unlistenProgress) {
    unlistenProgress();
    unlistenProgress = null;
  }
});
</script>
<template>
  <div
    v-if="ui.isDependencyModalOpen"
    class="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-in fade-in duration-150 select-none pointer-events-auto"
  >
    <div
      class="max-w-[380px] sm:max-w-[400px] w-full p-6 sm:p-7 rounded-[32px] bg-white border border-slate-100 shadow-[0_25px_60px_rgba(0,0,0,0.35)] text-center space-y-4 flex flex-col items-center animate-in zoom-in-95 duration-150 text-slate-900"
    >
