        println!("  📊 识别文本行数: {}", regions.len());
        println!("  预览前 10 句识别结果:");
        for (idx, reg) in regions.iter().take(10).enumerate() {
            println!("    [{:02}] [{:.2}]: {}", idx + 1, reg.score, reg.text);
