        let mut md_content = String::from("# ⚡ service-ocr 默认 PP-OCRv6 Small 物理打靶产物\n\n");
        for (idx, reg) in regions.iter().enumerate() {
            md_content.push_str(&format!("{}. **[{:.2}]**: {}\n", idx + 1, reg.score, reg.text));
