        let _ = std::fs::write(&out_md_path, md_content);
        println!("  💾 默认模型 OCR 物理产物成功落盘至:");
        println!("     - JSON: {:?}", out_json_path);
        println!("     - MD:   {:?}", out_md_path);
        println!("=======================================================\n");
        assert!(regions.len() > 0, "识别文本行数不可为 0！");
    }
