    pub target_scale: f32,
    pub max_output_side: u32,
    pub tile_size: u32,
    pub tile_pad: u32,
}
impl Default for UpscaleConfig {
    fn default() -> Self {
        Self {
            model_path: UpscaleService::resolve_default_model_path(),
