        println!("🚀 启动完整图片任务验证: {:?}", in_path);
        let res = UpscaleService::run_upscale(&task, None, Some(|cur, total, msg: &str| {
            println!("   [进度 {}/{}] {}", cur, total, msg);
        }))
        .await
        .expect("任务执行失败");
        println!("🎉 任务完成，总耗时: {} ms ({:.2} s)", res.elapsed_ms, res.elapsed_ms as f64 / 1000.0);
    }
