        let _ = fs::write(&out_chars_path, chars_json);
        let elapsed_ms = t0.elapsed().as_secs_f64() * 1000.0;
        println!("✅ service-pdfium 物理打靶通过: 总耗时 {:.2} ms | Point尺寸: {:.1}x{:.1}", elapsed_ms, w_pt, h_pt);
    }
