  const sorted = [...masterToolList].sort((a, b) => {
    const countA = ui.toolUsageCounts[a.id] || 0;
    const countB = ui.toolUsageCounts[b.id] || 0;
    return countB - countA;
  });
  return sorted.slice(0, 3).map((t) => ({
    id: t.id,
    image: t.image,
    title: t.name,
    subtitle: t.subtitle,
    viewTarget: t.viewTarget,
  }));
});
